-- --------------------------------------------------------
-- Struktur Tabel `settings`
-- --------------------------------------------------------
CREATE TABLE IF NOT EXISTS `settings` (
  `id` bigint(20) UNSIGNED NOT NULL AUTO_INCREMENT,
  `key` varchar(255) NOT NULL UNIQUE,
  `value` text DEFAULT NULL,
  `deskripsi` text DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


-- --------------------------------------------------------
-- Struktur Tabel `pegawais` (148 Pegawai Resmi BWS Kal I)
-- --------------------------------------------------------
CREATE TABLE IF NOT EXISTS `pegawais` (
  `id` bigint(20) UNSIGNED NOT NULL AUTO_INCREMENT,
  `nip` varchar(255) DEFAULT NULL,
  `nama` varchar(255) NOT NULL,
  `pangkat` varchar(255) DEFAULT NULL,
  `kelas` varchar(50) DEFAULT NULL,
  `jabatan` varchar(255) NOT NULL,
  `rangkap` varchar(255) DEFAULT NULL,
  `unit` varchar(255) DEFAULT NULL,
  `satker` varchar(255) DEFAULT NULL,
  `ket` text DEFAULT NULL,
  `jabatan_surat` varchar(255) DEFAULT NULL,
  `rangkap_surat` varchar(255) DEFAULT NULL,
  `nama_surat` varchar(255) DEFAULT NULL,
  `is_active` tinyint(1) NOT NULL DEFAULT 1,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `idx_pegawai_nip` (`nip`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


-- --------------------------------------------------------
-- Struktur Tabel `surat_undangans`
-- --------------------------------------------------------
CREATE TABLE IF NOT EXISTS `surat_undangans` (
  `id` bigint(20) UNSIGNED NOT NULL AUTO_INCREMENT,
  `nomor_surat` varchar(255) NOT NULL,
  `sifat` varchar(100) DEFAULT 'Biasa',
  `lampiran` varchar(100) DEFAULT '1 Berkas',
  `hal` varchar(255) NOT NULL,
  `tanggal_surat` date NOT NULL,
  `hari_tanggal_acara` varchar(255) DEFAULT NULL,
  `waktu_acara` varchar(255) DEFAULT NULL,
  `tempat` varchar(255) NOT NULL,
  `agenda` text DEFAULT NULL,
  `penandatangan_nama` varchar(255) NOT NULL,
  `penandatangan_nip` varchar(255) DEFAULT NULL,
  `penandatangan_jabatan` varchar(255) NOT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- --------------------------------------------------------
-- Struktur Tabel `surat_undangan_penerimas`
-- --------------------------------------------------------
CREATE TABLE IF NOT EXISTS `surat_undangan_penerimas` (
  `id` bigint(20) UNSIGNED NOT NULL AUTO_INCREMENT,
  `surat_undangan_id` bigint(20) UNSIGNED NOT NULL,
  `nama_penerima` varchar(255) NOT NULL,
  `urutan` int(11) DEFAULT 1,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `fk_undangan_penerima` (`surat_undangan_id`),
  CONSTRAINT `fk_undangan_penerima` FOREIGN KEY (`surat_undangan_id`) REFERENCES `surat_undangans` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

